// Process GitHub data and filter for the week
const commits = $input.all()[0].json || [];
const issues = $input.all()[1].json || [];
const prs = $input.all()[2].json || [];

const oneWeekAgo = new Date();
oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);

// Filter commits from last week
const weeklyCommits = commits.filter(c => 
  new Date(c.commit.author.date) >= oneWeekAgo
);

// Filter issues closed last week
const weeklyIssues = issues.filter(i => 
  new Date(i.closed_at) >= oneWeekAgo
);

// Filter PRs merged last week
const weeklyPRs = prs.filter(p => 
  p.merged_at && new Date(p.merged_at) >= oneWeekAgo
);

// Format data for Claude
const commitsList = weeklyCommits.slice(0, 20).map(c => ({
  message: c.commit.message.split('\n')[0],
  author: c.commit.author.name,
  date: c.commit.author.date,
  url: c.html_url
}));

const issuesList = weeklyIssues.slice(0, 20).map(i => ({
  title: i.title,
  number: i.number,
  url: i.html_url,
  labels: i.labels.map(l => l.name)
}));

const prsList = weeklyPRs.slice(0, 20).map(p => ({
  title: p.title,
  number: p.number,
  url: p.html_url,
  author: p.user.login,
  additions: p.additions,
  deletions: p.deletions
}));

return {
  json: {
    repo: $env.GITHUB_REPO,
    language: $env.LANGUAGE || 'EN',
    stats: {
      commits: weeklyCommits.length,
      issues: weeklyIssues.length,
      prs: weeklyPRs.length
    },
    commits: commitsList,
    issues: issuesList,
    prs: prsList,
    weekStart: oneWeekAgo.toISOString().split('T')[0],
    weekEnd: new Date().toISOString().split('T')[0]
  }
};

